fn validate_high_power_pa_override(settings: HighPowerPaOverride) -> Result<(), RadioError> {
    const HIGH_POWER_MIN: i8 = -9;
    const HIGH_POWER_MAX: i8 = 22;
    const SX1262_MAX_PA_DUTY_CYCLE: u8 = 0x04;
    const SX1262_MAX_HP_MAX: u8 = 0x07;
    const SX1262_MAX_OCP: u8 = 0x3f;

    let encoded_power = settings.tx_params_power as i8;
    let ocp_is_valid = match settings.ocp {
        Some(ocp) => ocp <= SX1262_MAX_OCP,
        None => true,
    };
    if settings.pa_duty_cycle > SX1262_MAX_PA_DUTY_CYCLE
        || settings.hp_max > SX1262_MAX_HP_MAX
        || !(HIGH_POWER_MIN..=HIGH_POWER_MAX).contains(&encoded_power)
        || !ocp_is_valid
    {
        return Err(RadioError::InvalidConfiguration);
    }
    Ok(())
}

